		neck1.xRot += Mth.sin(state.ageInTicks * 0.11F + 0.9F) * (0.1F + 0.12F * state.walkAnimationSpeed);
		neck2.zRot += Mth.sin(state.ageInTicks * 0.12000000000000001F + 1.8F) * (0.13F + 0.12F * state.walkAnimationSpeed);
		hood.yRot += Mth.sin(state.ageInTicks * 0.09F + 0.0F) * (0.04F + 0.0F * state.walkAnimationSpeed);
